import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { storage } from '../firebase';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { updateProfile } from 'firebase/auth';
import ImageCropper from '../components/ImageCropper';
import './ProfilePage.css';
import { Link, Navigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import { auth } from '../firebase';

const ADMIN_EMAILS = ['atulsinghdhakad15@gmail.com'];

const ProfilePage = () => {
  const { user, logout, setUser } = useAuth();
  const [isUploading, setIsUploading] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [showCropper, setShowCropper] = useState(false);
  const fileInputRef = useRef(null);
  const [uploadProgress, setUploadProgress] = useState(0);

  // Check if user is admin
  const isAdmin = ADMIN_EMAILS.includes(user?.email);

  // Check for locally stored profile picture
  useEffect(() => {
    if (user && user.uid) {
      const localProfilePic = localStorage.getItem(`profile_${user.uid}`);
      if (localProfilePic && (!user.photoURL || user.photoURL.startsWith('local://'))) {
        console.log('🔄 Found locally stored profile picture');
        // Update the user's photoURL with the local one
        updateProfile(user, {
          photoURL: localProfilePic
        }).catch(error => {
          console.error('Failed to update profile with local picture:', error);
        });
      }
    }
  }, [user]);

  // Handle logout
  const handleLogout = async () => {
    try {
      await logout();
      toast.success('Successfully signed out!');
    } catch (error) {
      console.error('Error logging out:', error);
      toast.error('Failed to sign out. Please try again.');
    }
  };

  // Get user initials for placeholder
  const getUserInitials = (name) => {
    if (!name) return 'U';
    return name
      .split(' ')
      .map(word => word.charAt(0))
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  // Trigger file input
  const triggerFileUpload = () => {
    console.log('🔘 Upload button clicked');
    console.log('📁 File input ref:', fileInputRef.current);
    
    if (fileInputRef.current) {
      console.log('✅ Triggering file input click');
      try {
        fileInputRef.current.click();
        console.log('✅ File input click triggered successfully');
      } catch (error) {
        console.error('❌ Error triggering file input:', error);
        toast.error('Failed to open file picker. Please try again.');
      }
    } else {
      console.log('❌ File input ref is null');
      toast.error('File upload not available. Please refresh the page.');
    }
  };

  // Handle file selection
  const handleFileSelect = (event) => {
    console.log('📁 File input changed:', event);
    console.log('📁 Files:', event.target.files);
    
    const file = event.target.files[0];
    if (file) {
      console.log('📁 Selected file:', {
        name: file.name,
        size: file.size,
        type: file.type
      });
      
      // Validate file type
      if (!file.type.startsWith('image/')) {
        console.log('❌ Invalid file type:', file.type);
        toast.error('Please select a valid image file.');
        // Clear the file input
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
        return;
      }

      // Validate file size (max 10MB)
      if (file.size > 10 * 1024 * 1024) {
        console.log('❌ File too large:', file.size);
        toast.error('Image size should be less than 10MB.');
        // Clear the file input
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
        return;
      }

      console.log('✅ File validation passed, starting local upload...');
      
      // Clear the file input first
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      
      // Use local-only upload since Firebase is not working
      handleLocalOnlyUpload(file)
        .catch(error => {
          console.error('❌ Local upload failed:', error);
          setIsUploading(false);
          setUploadProgress(0);
          toast.error(error.message || 'Upload failed. Please try again.');
        });
    } else {
      console.log('❌ No file selected');
    }
  };

  // Add image compression function
  const compressImage = (file, maxWidth = 800, quality = 0.7) => {
    return new Promise((resolve) => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      const img = new Image();
      
      img.onload = () => {
        // Calculate new dimensions
        let { width, height } = img;
        if (width > maxWidth) {
          height = (height * maxWidth) / width;
          width = maxWidth;
        }
        
        canvas.width = width;
        canvas.height = height;
        
        // Draw and compress
        ctx.drawImage(img, 0, 0, width, height);
        canvas.toBlob(resolve, 'image/jpeg', quality);
      };
      
      img.src = URL.createObjectURL(file);
    });
  };

  // Simple local upload (no Firebase)
  const handleLocalOnlyUpload = async (file) => {
    console.log('🔄 Starting local-only upload...');
    
    if (!file) {
      throw new Error('No file provided');
    }

    if (!user || !user.uid) {
      throw new Error('Please log in to upload a profile picture.');
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      // Compress image
      console.log('🔄 Compressing image...');
      const compressedBlob = await compressImage(file, 300, 0.7);
      console.log('✅ Image compressed, size:', compressedBlob.size);
      
      // Convert to base64
      console.log('🔄 Converting to base64...');
      const base64String = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(compressedBlob);
      });
      
      console.log('✅ Base64 conversion successful');
      
      // Store in localStorage
      localStorage.setItem(`profile_${user.uid}`, base64String);
      console.log('✅ Stored in localStorage');
      
      // Update user state
      setUser(prev => ({ ...prev, photoURL: base64String }));
      setIsUploading(false);
      setUploadProgress(100);
      
      toast.success('🎉 Profile picture updated! (Local storage only)', {
        duration: 4000,
        style: {
          background: 'linear-gradient(135deg, #667eea, #764ba2)',
          color: '#fff',
          fontWeight: 'bold',
        },
      });
      
      return true;
      
    } catch (error) {
      console.error('❌ Local upload failed:', error);
      setIsUploading(false);
      setUploadProgress(0);
      throw new Error(`Local upload failed: ${error.message}`);
    }
  };

  // Handle crop completion (for ImageCropper component)
  const handleCropComplete = async (croppedImageBlob) => {
    console.log('=== CROP COMPLETION STARTED ===');
    console.log('handleCropComplete called with blob:', croppedImageBlob);
    
    if (!croppedImageBlob) {
      console.error('❌ No cropped image blob received');
      toast.error('Failed to crop image. Please try again.');
      return;
    }

    console.log('✅ Blob details:', {
      size: croppedImageBlob.size,
      type: croppedImageBlob.type
    });

    if (croppedImageBlob.size === 0) {
      console.error('❌ Blob is empty (0 bytes)');
      toast.error('Cropped image is empty. Please try again.');
      return;
    }

    setIsUploading(true);
    
    try {
      // Convert blob to file
      const file = new File([croppedImageBlob], `profile-${Date.now()}.jpg`, {
        type: 'image/jpeg'
      });
      
      console.log('✅ Created file from blob:', {
        name: file.name,
        size: file.size,
        type: file.type
      });
      
      // Use local upload for cropped image
      await handleLocalOnlyUpload(file);
      
      // Close cropper and reset
      setShowCropper(false);
      setSelectedImage(null);
      
      // Clear the file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      
    } catch (error) {
      console.error('❌ Crop upload failed:', error);
      setIsUploading(false);
      setUploadProgress(0);
      toast.error(error.message || 'Failed to upload cropped image.');
    }
  };

  // Handle crop cancel
  const handleCropCancel = () => {
    setShowCropper(false);
    setSelectedImage(null);
    
    // Clear the file input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  // Function to get display photo URL
  const getDisplayPhotoURL = () => {
    if (!user) return null;
    
    // If user has a Firebase photoURL, use it
    if (user.photoURL && !user.photoURL.startsWith('local://')) {
      return user.photoURL;
    }
    
    // If user has a local photoURL, get from localStorage
    if (user.photoURL && user.photoURL.startsWith('local://')) {
      const localPhoto = localStorage.getItem(`profile_${user.uid}`);
      if (localPhoto) {
        return localPhoto;
      }
    }
    
    // Check if there's a stored photo in localStorage
    const localProfilePic = localStorage.getItem(`profile_${user.uid}`);
    if (localProfilePic) {
      return localProfilePic;
    }
    
    return null;
  };

  // If user is not logged in, redirect to login page
  if (!user) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className="modern-profile-page">
      {/* Animated Background */}
      <div className="animated-background">
        <div className="gradient-orb orb-1"></div>
        <div className="gradient-orb orb-2"></div>
        <div className="gradient-orb orb-3"></div>
        <div className="floating-particles">
          {[...Array(20)].map((_, i) => (
            <div key={i} className="particle" style={{ '--delay': `${i * 0.1}s` }}></div>
          ))}
        </div>
      </div>

      {/* Main Container */}
      <div className="profile-container">
        {/* Header Section */}
        <div className="profile-header">
          <div className="header-content">
            <h1 className="page-title">
              <span className="title-icon">👤</span>
              Profile Dashboard
            </h1>
            <p className="page-subtitle">Manage your account and preferences</p>
          </div>
        </div>

        {/* Main Profile Section */}
        <div className="profile-main">
          {/* Left Column - Profile Card */}
          <div className="profile-card">
            <div className="card-header">
              <h2 className="card-title">Profile Information</h2>
            </div>
            
            <div className="profile-content">
              {/* Profile Image Section */}
              <div className="profile-image-section">
                <div className="modern-avatar-container">
                  <div className="avatar-wrapper">
                    {getDisplayPhotoURL() && (
                      <img
                        src={getDisplayPhotoURL()}
                        alt="Profile"
                        className="profile-avatar"
                      />
                    )}
                    {!getDisplayPhotoURL() && (
                      <div className="profile-avatar-placeholder">
                        {getUserInitials(user?.displayName)}
                      </div>
                    )}
                    <div className="avatar-rings">
                      <div className="ring ring-1"></div>
                      <div className="ring ring-2"></div>
                      <div className="ring ring-3"></div>
                    </div>
                    
                    {/* Upload Overlay */}
                    <div className="upload-overlay">
                      <button
                        onClick={triggerFileUpload}
                        disabled={isUploading}
                        className="upload-btn"
                        title="Change Profile Picture"
                      >
                        {isUploading ? (
                          <div className="upload-spinner"></div>
                        ) : (
                          <span>📷</span>
                        )}
                      </button>
                    </div>
                  </div>
                </div>

                {/* Upload Button */}
                <button
                  onClick={triggerFileUpload}
                  disabled={isUploading}
                  className="modern-upload-button"
                  title="Upload New Profile Picture"
                >
                  {isUploading ? (
                    <>
                      <div className="loading-spinner"></div>
                      <span>Uploading...</span>
                    </>
                  ) : (
                    <>
                      <span className="btn-icon">📷</span>
                      <span className="btn-text">Change Photo</span>
                    </>
                  )}
                </button>
              </div>

              {/* User Info Section */}
              <div className="user-info-section">
                <div className="info-grid">
                  <div className="info-item">
                    <div className="info-icon">👤</div>
                    <div className="info-content">
                      <label className="info-label">Display Name</label>
                      <div className="info-value">{user?.displayName || 'Not set'}</div>
                    </div>
                  </div>

                  <div className="info-item">
                    <div className="info-icon">📧</div>
                    <div className="info-content">
                      <label className="info-label">Email Address</label>
                      <div className="info-value">{user?.email || 'Not available'}</div>
                    </div>
                  </div>

                  <div className="info-item">
                    <div className="info-icon">🆔</div>
                    <div className="info-content">
                      <label className="info-label">Account Type</label>
                      <div className="info-value">
                        {isAdmin ? (
                          <span className="modern-admin-badge">
                            <span className="badge-icon">🛡️</span>
                            <span className="badge-text">Administrator</span>
                            <div className="badge-glow"></div>
                          </span>
                        ) : (
                          <span className="user-badge">
                            <span className="badge-icon">👤</span>
                            <span className="badge-text">User</span>
                          </span>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="info-item">
                    <div className="info-icon">📅</div>
                    <div className="info-content">
                      <label className="info-label">Member Since</label>
                      <div className="info-value">
                        {user?.metadata?.creationTime ? 
                          new Date(user.metadata.creationTime).toLocaleDateString('en-US', {
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric'
                          }) : 
                          'Unknown'
                        }
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column - Quick Actions */}
          <div className="quick-actions-card">
            <div className="card-header">
              <h2 className="card-title">Quick Actions</h2>
            </div>
            
            <div className="actions-grid">
              <Link to="/settings" className="action-item settings-action">
                <div className="action-icon">⚙️</div>
                <div className="action-content">
                  <h3 className="action-title">Settings</h3>
                  <p className="action-description">Manage your preferences</p>
                </div>
                <div className="action-arrow">→</div>
              </Link>

              {isAdmin && (
                <Link to="/adminpanel" className="action-item admin-action">
                  <div className="action-icon">🛡️</div>
                  <div className="action-content">
                    <h3 className="action-title">Admin Panel</h3>
                    <p className="action-description">Manage the platform</p>
                  </div>
                  <div className="action-arrow">→</div>
                </Link>
              )}

              <button onClick={handleLogout} className="action-item logout-action">
                <div className="action-icon">🚪</div>
                <div className="action-content">
                  <h3 className="action-title">Sign Out</h3>
                  <p className="action-description">Logout from your account</p>
                </div>
                <div className="action-arrow">→</div>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Hidden File Input */}
      <input
        type="file"
        ref={fileInputRef}
        accept="image/*"
        onChange={handleFileSelect}
        className="hidden-file-input"
        style={{ display: 'none' }}
      />

      {/* Image Cropper Modal */}
      {showCropper && selectedImage && (
        <ImageCropper
          imageSrc={selectedImage}
          onCrop={handleCropComplete}
          onClose={handleCropCancel}
        />
      )}
    </div>
  );
};

export default ProfilePage; 