// src/pages/AdminPanel.jsx

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth } from '../firebase';
import Swal from 'sweetalert2';
import withReactContent from 'sweetalert2-react-content';
import axios from 'axios';
import { motion } from 'framer-motion';
import { toast } from 'react-hot-toast';
import { saveAs } from 'file-saver';
import jsPDF from 'jspdf';

const MySwal = withReactContent(Swal);

const AdminPanel = () => {
  const [user, setUser] = useState(null);
  const [contacts, setContacts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedContacts, setSelectedContacts] = useState([]);
  const [showContactModal, setShowContactModal] = useState(false);
  const [selectedContact, setSelectedContact] = useState(null);
  const [filterDate, setFilterDate] = useState('');
  const contactsPerPage = 5;
  const navigate = useNavigate();

  const playSound = () => {
    const audio = new Audio('/sounds/ding.mp3');
    audio.play().catch(err => console.log('Autoplay prevented:', err));
  };

  useEffect(() => {
    // Check if admin is authenticated
    const isAuthenticated = localStorage.getItem('admin_authenticated') === 'true';
    if (!isAuthenticated) {
      navigate('/admin/login');
      return;
    }

    const adminEmail = localStorage.getItem('admin_email') || 'admin@coachingfinder.com';
    setUser({ username: 'admin', email: adminEmail });
    
    // Only show welcome message once
    const hasShownWelcome = sessionStorage.getItem('admin_welcome_shown');
    if (!hasShownWelcome) {
      playSound();
      toast.success(`🎉 Welcome, ${adminEmail}!`, {
        duration: 3000,
        position: 'top-center',
        style: {
          background: 'linear-gradient(to right, #8e2de2, #4a00e0)',
          color: '#fff',
          fontWeight: 'bold',
          fontSize: '16px',
          padding: '12px 20px',
          borderRadius: '10px',
          boxShadow: '0px 4px 10px rgba(0,0,0,0.2)',
        },
        icon: '🔒',
      });
      sessionStorage.setItem('admin_welcome_shown', 'true');
    }
  }, [navigate]);

  const fetchContacts = async () => {
    try {
      const adminToken = localStorage.getItem('admin_token');
      const response = await axios.get('http://localhost:5001/api/admin/contacts', {
        headers: {
          Authorization: `Bearer ${adminToken}`,
        },
      });
      setContacts(response.data.reverse());
    } catch (error) {
      console.error('Error fetching contacts:', error);
      if (error.response?.status === 401) {
        // Unauthorized - redirect to login
        localStorage.removeItem('admin_token');
        localStorage.removeItem('admin_authenticated');
        navigate('/admin/login');
        toast.error('Session expired. Please login again.');
      } else {
        toast.error('Failed to fetch contacts');
      }
    }
  };

  useEffect(() => {
    fetchContacts();
  }, []);

  const handleExitAdmin = async () => {
    const result = await MySwal.fire({
      title: 'Logout from Admin?',
      text: 'You will be logged out and redirected to login.',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#7C3AED',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Yes, Logout',
      background: '#f9fafb',
    });

    if (result.isConfirmed) {
      // Clear admin authentication and welcome flag
      localStorage.removeItem('admin_token');
      localStorage.removeItem('admin_authenticated');
      localStorage.removeItem('admin_email');
      sessionStorage.removeItem('admin_welcome_shown');
      
      playSound();
      MySwal.fire('Logged Out', 'You have been logged out successfully.', 'success');
      toast.success('Logged out successfully.', {
        style: {
          background: 'linear-gradient(to right, #FF5733, #FF8000)',
          color: '#fff',
          fontWeight: 'bold',
          borderRadius: '10px'
        },
      });
      navigate('/admin/login');
    }
  };

  const totalSubmissions = contacts.length;
  const lastSubmissionTime = contacts[0]?.createdAt ? new Date(contacts[0].createdAt).toLocaleString() : 'N/A';
  const lastUserEmail = contacts[0]?.email || 'N/A';

  const downloadCSV = () => {
    const csvRows = [
      ['Name', 'Email', 'Message', 'Submitted At'],
      ...contacts.map(c => [
        `"${c.name}"`, `"${c.email}"`, `"${c.message}"`, `"${new Date(c.createdAt).toLocaleString()}"`
      ])
    ];
    const blob = new Blob([csvRows.map(r => r.join(',')).join('\n')], { type: 'text/csv;charset=utf-8;' });
    saveAs(blob, 'contacts.csv');
    toast.success('📅 CSV Downloaded!', {
      style: {
        background: 'linear-gradient(to right, #00b09b, #96c93d)',
        color: '#fff',
        fontWeight: 'bold'
      },
      position: 'top-center'
    });
  };

  const downloadPDF = () => {
    const doc = new jsPDF();
    
    // Add title
    doc.setFontSize(20);
    doc.text('Contact Submissions Report', 14, 22);
    doc.setFontSize(12);
    doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 32);
    doc.text(`Total Submissions: ${contacts.length}`, 14, 42);
    
    // Create table manually
    let yPosition = 60;
    const pageHeight = doc.internal.pageSize.height;
    const margin = 14;
    const maxWidth = doc.internal.pageSize.width - (2 * margin);
    
    // Add headers
    doc.setFontSize(10);
    doc.setFont(undefined, 'bold');
    doc.text('Name', margin, yPosition);
    doc.text('Email', margin + 50, yPosition);
    doc.text('Message', margin + 100, yPosition);
    doc.text('Date', margin + 160, yPosition);
    
    yPosition += 10;
    doc.setFont(undefined, 'normal');
    
    // Add data rows
    contacts.forEach((contact, index) => {
      // Check if we need a new page
      if (yPosition > pageHeight - 20) {
        doc.addPage();
        yPosition = 20;
      }
      
      const name = contact.name.length > 20 ? contact.name.substring(0, 20) + '...' : contact.name;
      const email = contact.email.length > 25 ? contact.email.substring(0, 25) + '...' : contact.email;
      const message = contact.message.length > 30 ? contact.message.substring(0, 30) + '...' : contact.message;
      const date = new Date(contact.createdAt).toLocaleDateString();
      
      doc.text(name, margin, yPosition);
      doc.text(email, margin + 50, yPosition);
      doc.text(message, margin + 100, yPosition);
      doc.text(date, margin + 160, yPosition);
      
      yPosition += 8;
    });
    
    // Save PDF
    doc.save('contacts-report.pdf');
    toast.success('📄 PDF Downloaded!', {
      style: {
        background: 'linear-gradient(to right, #ff6b6b, #ee5a24)',
        color: '#fff',
        fontWeight: 'bold'
      },
      position: 'top-center'
    });
  };

  const handleDelete = async (id) => {
    const result = await MySwal.fire({
      title: 'Delete Contact?',
      text: 'This cannot be undone!',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#e3342f',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Yes, Delete!'
    });

    if (result.isConfirmed) {
      try {
        const adminToken = localStorage.getItem('admin_token');
        await axios.delete(`http://localhost:5001/api/admin/contact/${id}`, {
          headers: {
            Authorization: `Bearer ${adminToken}`,
          },
        });
        fetchContacts();
        toast.success('✅ Contact Deleted!', {
          position: 'top-center',
          style: { background: 'linear-gradient(to right, #ff416c, #ff4b2b)', color: '#fff' }
        });
      } catch (error) {
        console.error('Error deleting contact:', error);
        if (error.response?.status === 401) {
          localStorage.removeItem('admin_token');
          localStorage.removeItem('admin_authenticated');
          navigate('/admin/login');
          toast.error('Session expired. Please login again.');
        } else {
          toast.error('Failed to delete contact');
        }
      }
    }
  };

  const paginate = (pageNumber) => {
    setCurrentPage(pageNumber);
    toast.success(`Page ${pageNumber}`, {
      position: 'bottom-center',
      style: { fontWeight: 'bold' }
    });
  };

  // Bulk operations
  const handleSelectAll = () => {
    if (selectedContacts.length === currentContacts.length) {
      setSelectedContacts([]);
    } else {
      setSelectedContacts(currentContacts.map(c => c._id));
    }
  };

  const handleSelectContact = (id) => {
    if (selectedContacts.includes(id)) {
      setSelectedContacts(selectedContacts.filter(c => c !== id));
    } else {
      setSelectedContacts([...selectedContacts, id]);
    }
  };

  const handleBulkDelete = async () => {
    if (selectedContacts.length === 0) {
      toast.error('No contacts selected');
      return;
    }

    const result = await MySwal.fire({
      title: `Delete ${selectedContacts.length} contacts?`,
      text: 'This cannot be undone!',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#e3342f',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Yes, Delete All!'
    });

    if (result.isConfirmed) {
      try {
        const adminToken = localStorage.getItem('admin_token');
        const response = await axios.delete('http://localhost:5001/api/admin/contacts/bulk', {
          headers: {
            Authorization: `Bearer ${adminToken}`,
            'Content-Type': 'application/json',
          },
          data: { ids: selectedContacts }
        });
        
        setSelectedContacts([]);
        fetchContacts();
        toast.success(`✅ ${response.data.deletedCount} contacts deleted!`, {
          position: 'top-center',
          style: { background: 'linear-gradient(to right, #ff416c, #ff4b2b)', color: '#fff' }
        });
      } catch (error) {
        console.error('Error bulk deleting contacts:', error);
        if (error.response?.status === 401) {
          localStorage.removeItem('admin_token');
          localStorage.removeItem('admin_authenticated');
          navigate('/admin/login');
          toast.error('Session expired. Please login again.');
        } else {
          toast.error('Failed to delete contacts');
        }
      }
    }
  };

  // Contact details modal
  const showContactDetails = (contact) => {
    setSelectedContact(contact);
    setShowContactModal(true);
  };

  // Advanced filtering
  const filteredContacts = contacts.filter(c => {
    const matchesSearch = c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         c.message.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesDate = !filterDate || 
                       new Date(c.createdAt).toDateString() === new Date(filterDate).toDateString();
    
    return matchesSearch && matchesDate;
  });

  const currentContacts = filteredContacts.slice((currentPage - 1) * contactsPerPage, currentPage * contactsPerPage);

  if (!user) return (
    <div className="flex justify-center items-center min-h-screen text-lg text-purple-500">
      Loading Admin Panel...
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 p-8 text-black dark:text-white">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-between items-center mb-8">
          {/* <h1 className="text-3xl font-bold text-purple-600 text-center">Admin Panel!</h1> */}
          
        </div>



        <div className="flex justify-between items-center bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 space-y-4 mb-8">
  {/* Left: Welcome Panel */}
  <div>
    <h2 className="text-2xl font-semibold mb-2 font-bold text-purple-600">🎉 Welcome, Admin!</h2>
    {user.photoURL && <img src={user.photoURL} alt="Admin" className="w-12 h-12 rounded-full" />}
    <p><strong>Email:</strong> {user.email}</p>
    <p className="text-gray-600 dark:text-gray-400 mt-2">
      You now have access to manage contacts, view submissions, download reports, and more.
    </p>
  </div>

  {/* Right: Exit Admin Button */}
  <button
    onClick={handleExitAdmin}
    className="bg-purple-600 hover:bg-purple-700 text-white font-semibold py-2 px-4 rounded-lg transition-all duration-300"
  >
    Exit Admin
  </button>
</div>




        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-4xl font-bold text-purple-600">Admin Dashboard</h1>
            <p className="text-lg mt-2">Manage your contacts and submissions easily ✨</p>
          </div>
          <div className="flex space-x-3">
            <button onClick={downloadCSV} className="bg-green-500 hover:bg-green-600 text-white py-2 px-4 rounded-lg transition-all duration-300">
              📄 Download CSV
            </button>
            <button onClick={downloadPDF} className="bg-red-500 hover:bg-red-600 text-white py-2 px-4 rounded-lg transition-all duration-300">
              📋 Download PDF
            </button>
          </div>
        </div>

        <div className="mb-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
            <input
              type="text"
              placeholder="Search by name, email or message..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full p-3 rounded-lg border dark:border-gray-700 bg-gray-50 dark:bg-gray-700"
            />
            <input
              type="date"
              value={filterDate}
              onChange={(e) => setFilterDate(e.target.value)}
              className="w-full p-3 rounded-lg border dark:border-gray-700 bg-gray-50 dark:bg-gray-700"
            />
            <button
              onClick={() => setFilterDate('')}
              className="bg-gray-500 hover:bg-gray-600 text-white py-3 px-4 rounded-lg transition-all duration-300"
            >
              Clear Filters
            </button>
          </div>
          
          {selectedContacts.length > 0 && (
            <div className="bg-yellow-100 border border-yellow-400 text-yellow-700 px-4 py-3 rounded-lg mb-4">
              <div className="flex justify-between items-center">
                <span>{selectedContacts.length} contact(s) selected</span>
                <button
                  onClick={handleBulkDelete}
                  className="bg-red-500 hover:bg-red-600 text-white py-1 px-3 rounded-lg text-sm"
                >
                  Delete Selected
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
          <motion.div className="p-6 rounded-lg shadow-lg bg-gradient-to-r from-purple-400 to-purple-600 text-white text-center" whileHover={{ scale: 1.05 }}>
            <h2 className="text-3xl font-bold mb-2">{totalSubmissions}</h2>
            <p>Total Submissions</p>
          </motion.div>
          <motion.div className="p-6 rounded-lg shadow-lg bg-gradient-to-r from-blue-400 to-blue-600 text-white text-center" whileHover={{ scale: 1.05 }}>
            <h2 className="text-xl font-bold mb-2">{lastSubmissionTime}</h2>
            <p>Last Submission</p>
          </motion.div>
          <motion.div className="p-6 rounded-lg shadow-lg bg-gradient-to-r from-green-400 to-green-600 text-white text-center" whileHover={{ scale: 1.05 }}>
            <h2 className="text-xl font-bold mb-2">{lastUserEmail}</h2>
            <p>Latest User</p>
          </motion.div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
            <thead className="text-xs text-gray-700 uppercase bg-gray-200 dark:bg-gray-700 dark:text-gray-300">
              <tr>
                <th className="py-3 px-6">
                  <input
                    type="checkbox"
                    checked={selectedContacts.length === currentContacts.length && currentContacts.length > 0}
                    onChange={handleSelectAll}
                    className="rounded"
                  />
                </th>
                <th className="py-3 px-6">Name</th>
                <th className="py-3 px-6">Email</th>
                <th className="py-3 px-6">Message</th>
                <th className="py-3 px-6">Submitted At</th>
                <th className="py-3 px-6">Actions</th>
              </tr>
            </thead>
            <tbody>
              {currentContacts.map((c, idx) => (
                <motion.tr key={idx} className="bg-white dark:bg-gray-800 border-b hover:scale-[1.01] transition-transform" whileHover={{ scale: 1.02 }}>
                  <td className="py-4 px-6">
                    <input
                      type="checkbox"
                      checked={selectedContacts.includes(c._id)}
                      onChange={() => handleSelectContact(c._id)}
                      className="rounded"
                    />
                  </td>
                  <td className="py-4 px-6">{c.name}</td>
                  <td className="py-4 px-6">{c.email}</td>
                  <td className="py-4 px-6">{c.message.length > 50 ? c.message.substring(0, 50) + '...' : c.message}</td>
                  <td className="py-4 px-6">{new Date(c.createdAt).toLocaleString()}</td>
                  <td className="py-4 px-6">
                    <div className="flex space-x-2">
                      <button 
                        onClick={() => showContactDetails(c)} 
                        className="bg-blue-500 hover:bg-blue-600 text-white py-1 px-3 rounded-full text-xs"
                      >
                        View
                      </button>
                      <button 
                        onClick={() => handleDelete(c._id)} 
                        className="bg-red-500 hover:bg-red-600 text-white py-1 px-3 rounded-full text-xs"
                      >
                        Delete
                      </button>
                    </div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="flex justify-center mt-8 space-x-2">
          {Array.from({ length: Math.ceil(filteredContacts.length / contactsPerPage) }, (_, idx) => (
            <button
              key={idx}
              onClick={() => paginate(idx + 1)}
              className={`py-1 px-3 rounded-full ${currentPage === idx + 1 ? 'bg-purple-600 text-white' : 'bg-gray-300 dark:bg-gray-700 text-black dark:text-white'} transition-all duration-300`}
            >
              {idx + 1}
            </button>
          ))}
        </div>
      </div>

      {/* Contact Details Modal */}
      {showContactModal && selectedContact && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-gray-800 rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[80vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-2xl font-bold text-purple-600">Contact Details</h2>
              <button
                onClick={() => setShowContactModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>
            
            <div className="space-y-4">
              <div>
                <label className="font-semibold text-gray-700 dark:text-gray-300">Name:</label>
                <p className="text-lg">{selectedContact.name}</p>
              </div>
              
              <div>
                <label className="font-semibold text-gray-700 dark:text-gray-300">Email:</label>
                <p className="text-lg">{selectedContact.email}</p>
              </div>
              
              <div>
                <label className="font-semibold text-gray-700 dark:text-gray-300">Message:</label>
                <p className="text-lg whitespace-pre-wrap bg-gray-50 dark:bg-gray-700 p-3 rounded-lg">
                  {selectedContact.message}
                </p>
              </div>
              
              <div>
                <label className="font-semibold text-gray-700 dark:text-gray-300">Submitted At:</label>
                <p className="text-lg">{new Date(selectedContact.createdAt).toLocaleString()}</p>
              </div>
            </div>
            
            <div className="flex justify-end space-x-3 mt-6">
              <button
                onClick={() => setShowContactModal(false)}
                className="bg-gray-500 hover:bg-gray-600 text-white py-2 px-4 rounded-lg"
              >
                Close
              </button>
              <button
                onClick={() => {
                  handleDelete(selectedContact._id);
                  setShowContactModal(false);
                }}
                className="bg-red-500 hover:bg-red-600 text-white py-2 px-4 rounded-lg"
              >
                Delete Contact
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;
