import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { signOut, updateProfile } from 'firebase/auth';
import { auth } from '../firebase';
import Swal from 'sweetalert2';
import withReactContent from 'sweetalert2-react-content';
import { toast } from 'react-hot-toast';
import ImageCropper from './ImageCropper';
import './ProfileDropdown.css';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { storage } from '../firebase';

const ADMIN_EMAILS = ['atulsinghdhakad15@gmail.com'];
const MySwal = withReactContent(Swal);

const ProfileDropdown = ({ user, darkMode, onLogout }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showCropper, setShowCropper] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [hoveredItem, setHoveredItem] = useState(null);
  const dropdownRef = useRef(null);
  const fileInputRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = async () => {
    const result = await MySwal.fire({
      title: '🚀 Sign Out',
      text: 'Ready to blast off?',
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#FF6B6B',
      cancelButtonColor: '#4ECDC4',
      confirmButtonText: '🚀 Launch',
      cancelButtonText: 'Stay',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: '#fff',
    });

    if (result.isConfirmed) {
      try {
        await signOut(auth);
        toast.success('🚀 Launched into orbit!', {
          style: {
            background: 'linear-gradient(135deg, #FF6B6B, #4ECDC4)',
            color: '#fff',
            fontWeight: 'bold',
          },
        });
        navigate('/');
      } catch (error) {
        console.error('Logout error:', error);
        toast.error('Launch failed. Please try again.');
      }
    }
  };

  const handleAdminLogout = async () => {
    const result = await MySwal.fire({
      title: '🛡️ Admin Logout',
      text: 'Sign out from admin panel?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#FF6B6B',
      cancelButtonColor: '#4ECDC4',
      confirmButtonText: '🛡️ Admin Logout',
      cancelButtonText: 'Cancel',
      background: 'linear-gradient(135deg, #FF6B6B 0%, #4ECDC4 100%)',
      color: '#fff',
    });

    if (result.isConfirmed) {
      try {
        // Clear admin session
        sessionStorage.removeItem('adminToken');
        sessionStorage.removeItem('adminUser');
        
        toast.success('🛡️ Admin session ended!', {
          style: {
            background: 'linear-gradient(135deg, #FF6B6B, #4ECDC4)',
            color: '#fff',
            fontWeight: 'bold',
          },
        });
        
        // Navigate to admin login
        navigate('/adminlogin');
      } catch (error) {
        console.error('Admin logout error:', error);
        toast.error('Admin logout failed. Please try again.');
      }
    }
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please select a valid image file.');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      toast.error('Image size should be less than 10MB.');
      return;
    }

    // Temporarily bypass cropper and upload directly
    handleDirectUpload(file);
    setIsOpen(false);
  };

  const handleTestFirebase = async () => {
    console.log('🧪 Testing Firebase connection...');
    console.log('👤 User:', user);
    console.log('🔥 Storage:', storage);
    
    try {
      // Test if we can create a simple text file
      const testContent = 'This is a test file';
      const testBlob = new Blob([testContent], { type: 'text/plain' });
      const testFile = new File([testBlob], 'test.txt', { type: 'text/plain' });
      
      console.log('📁 Test file created:', testFile);
      
      const testRef = ref(storage, `test/${user.uid}/test-${Date.now()}.txt`);
      console.log('🔥 Test storage ref:', testRef.fullPath);
      
      const snapshot = await uploadBytes(testRef, testFile);
      console.log('✅ Test upload successful:', snapshot);
      
      const downloadURL = await getDownloadURL(snapshot.ref);
      console.log('🔗 Test download URL:', downloadURL);
      
      toast.success('✅ Firebase test successful!', {
        style: {
          background: 'linear-gradient(135deg, #4CAF50, #45a049)',
          color: '#fff',
          fontWeight: 'bold',
        },
      });
      
    } catch (error) {
      console.error('❌ Firebase test failed:', error);
      toast.error(`Firebase test failed: ${error.message}`);
    }
  };

  const handleDirectUpload = async (file) => {
    console.log('🚀 Starting direct upload...');
    console.log('👤 User object:', user);
    console.log('👤 User UID:', user?.uid);
    console.log('👤 User email:', user?.email);
    console.log('📁 File details:', {
      name: file.name,
      size: file.size,
      type: file.type
    });
    
    // Check if user is authenticated
    if (!user || !user.uid) {
      console.error('❌ User not authenticated');
      toast.error('Please log in to upload a profile picture.');
      return;
    }
    
    // Check if file is valid
    if (!file || file.size === 0) {
      console.error('❌ Invalid file');
      toast.error('Please select a valid image file.');
      return;
    }
    
    setIsUploading(true);
    try {
      console.log('🔥 Creating Firebase storage reference...');
      const storageRef = ref(storage, `profile-pictures/${user.uid}/${Date.now()}_profile.png`);
      console.log('🔥 Storage ref created:', storageRef.fullPath);
      
      console.log('⬆️ Starting upload...');
      const snapshot = await uploadBytes(storageRef, file);
      console.log('✅ Upload successful:', {
        bytesTransferred: snapshot.bytesTransferred,
        totalBytes: snapshot.totalBytes,
        ref: snapshot.ref.fullPath
      });
      
      console.log('🔗 Getting download URL...');
      const downloadURL = await getDownloadURL(snapshot.ref);
      console.log('🔗 Download URL:', downloadURL);
      
      console.log('👤 Updating Firebase profile...');
      await updateProfile(user, {
        photoURL: downloadURL
      });
      console.log('✅ Profile updated successfully');

      toast.success('✨ Profile picture updated!', {
        style: {
          background: 'linear-gradient(135deg, #667eea, #764ba2)',
          color: '#fff',
          fontWeight: 'bold',
        },
      });

      setSelectedImage(null);
      console.log('🔄 Reloading page...');
      window.location.reload();
    } catch (error) {
      console.error('❌ Error updating profile picture:', error);
      console.error('❌ Error details:', {
        message: error.message,
        code: error.code,
        stack: error.stack
      });
      toast.error(`Failed to update profile picture: ${error.message}`);
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleCropComplete = async (blob) => {
    console.log('🎯 handleCropComplete called with blob:', blob);
    console.log('🎯 Blob details:', {
      size: blob?.size,
      type: blob?.type,
      lastModified: blob?.lastModified
    });
    
    setIsUploading(true);
    try {
      console.log('📁 Creating File from blob...');
      const file = new File([blob], `profile-${Date.now()}.png`, { type: 'image/png' });
      console.log('📁 File created:', {
        name: file.name,
        size: file.size,
        type: file.type,
        lastModified: file.lastModified
      });
      
      console.log('🔥 Creating Firebase storage reference...');
      const storageRef = ref(storage, `profile-pictures/${user.uid}/${Date.now()}_profile.png`);
      console.log('🔥 Storage ref created:', storageRef.fullPath);
      
      console.log('⬆️ Starting upload...');
      const snapshot = await uploadBytes(storageRef, file);
      console.log('✅ Upload successful:', {
        bytesTransferred: snapshot.bytesTransferred,
        totalBytes: snapshot.totalBytes,
        ref: snapshot.ref.fullPath
      });
      
      console.log('🔗 Getting download URL...');
      const downloadURL = await getDownloadURL(snapshot.ref);
      console.log('🔗 Download URL:', downloadURL);
      
      console.log('👤 Updating Firebase profile...');
      await updateProfile(user, {
        photoURL: downloadURL
      });
      console.log('✅ Profile updated successfully');

      toast.success('✨ Profile picture updated!', {
        style: {
          background: 'linear-gradient(135deg, #667eea, #764ba2)',
          color: '#fff',
          fontWeight: 'bold',
        },
      });

      setShowCropper(false);
      setSelectedImage(null);
      console.log('🔄 Reloading page...');
      window.location.reload();
    } catch (error) {
      console.error('❌ Error updating profile picture:', error);
      console.error('❌ Error details:', {
        message: error.message,
        code: error.code,
        stack: error.stack
      });
      toast.error('Failed to update profile picture. Please try again.');
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleCropCancel = () => {
    setShowCropper(false);
    setSelectedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  const getUserInitials = (name) => {
    if (!name) return 'U';
    return name
      .split(' ')
      .map(word => word.charAt(0))
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  const isAdmin = ADMIN_EMAILS.includes(user.email);
  const isAdminLoggedIn = sessionStorage.getItem('adminToken');

  return (
    <>
      <div className="relative profile-dropdown" ref={dropdownRef}>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleFileSelect}
          className="hidden"
        />

        {/* Futuristic Profile Button */}
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="futuristic-profile-btn group"
        >
          {/* Holographic Avatar */}
          <div className="holographic-avatar">
            {user.photoURL ? (
              <img
                src={user.photoURL}
                alt="Profile"
                className="avatar-image"
              />
            ) : (
              <div className="avatar-placeholder">
                {getUserInitials(user.displayName)}
              </div>
            )}
            <div className="holographic-ring"></div>
            <div className="holographic-ring ring-2"></div>
            <div className="holographic-ring ring-3"></div>
          </div>

          {/* User Info - Hidden on mobile */}
          <div className="user-info">
            <p className="user-name">{user.displayName || 'User'}</p>
            <p className="user-email">{user.email}</p>
          </div>

          {/* Animated Arrow */}
          <div className={`arrow-container ${isOpen ? 'open' : ''}`}>
            <div className="arrow"></div>
          </div>
        </button>

        {/* Futuristic Dropdown Menu */}
        {isOpen && (
          <div className="futuristic-dropdown">
            {/* Floating Particles */}
            <div className="particles">
              {[...Array(10)].map((_, i) => (
                <div key={i} className="particle" style={{ '--delay': `${i * 0.1}s` }}></div>
              ))}
            </div>

            {/* Header Section */}
            <div className="dropdown-header">
              <div className="profile-section">
                {/* Large Holographic Avatar */}
                <div className="large-holographic-avatar">
                  {user.photoURL ? (
                    <img
                      src={user.photoURL}
                      alt="Profile"
                      className="large-avatar-image"
                    />
                  ) : (
                    <div className="large-avatar-placeholder">
                      {getUserInitials(user.displayName)}
                    </div>
                  )}
                  <div className="large-holographic-ring"></div>
                  <div className="large-holographic-ring ring-2"></div>
                  <div className="large-holographic-ring ring-3"></div>
                  
                  {/* Upload Overlay */}
                  <div className="upload-overlay">
                    <button
                      onClick={triggerFileUpload}
                      disabled={isUploading}
                      className="upload-btn"
                    >
                      {isUploading ? '⚡' : '📷'}
                    </button>
                  </div>
                </div>

                {/* User Details */}
                <div className="user-details">
                  <h3 className="user-title">{user.displayName || 'User'}</h3>
                  <p className="user-subtitle">{user.email}</p>
                  {isAdmin && (
                    <div className="admin-badge">
                      <span className="badge-text">ADMIN</span>
                      <div className="badge-glow"></div>
                    </div>
                  )}
                </div>
              </div>

              {/* Upload Button */}
              <button
                onClick={triggerFileUpload}
                disabled={isUploading}
                className="upload-button"
              >
                {isUploading ? (
                  <>
                    <div className="loading-spinner"></div>
                    <span>Uploading...</span>
                  </>
                ) : (
                  <>
                    <span>📷</span>
                    <span>Change Photo</span>
                  </>
                )}
              </button>

              {/* Test Firebase Button */}
              <button
                onClick={handleTestFirebase}
                className="upload-button test-button"
                style={{ marginTop: '10px', backgroundColor: '#4CAF50' }}
              >
                <span>🧪</span>
                <span>Test Firebase</span>
              </button>
            </div>

            {/* Menu Items */}
            <div className="menu-items">
              <Link
                to="/profile"
                onClick={() => setIsOpen(false)}
                className={`menu-item ${hoveredItem === 'profile' ? 'hovered' : ''}`}
                onMouseEnter={() => setHoveredItem('profile')}
                onMouseLeave={() => setHoveredItem(null)}
              >
                <div className="item-icon">👤</div>
                <span className="item-text">Profile</span>
                <div className="item-glow"></div>
              </Link>

              <Link
                to="/settings"
                onClick={() => setIsOpen(false)}
                className={`menu-item ${hoveredItem === 'settings' ? 'hovered' : ''}`}
                onMouseEnter={() => setHoveredItem('settings')}
                onMouseLeave={() => setHoveredItem(null)}
              >
                <div className="item-icon">⚙️</div>
                <span className="item-text">Settings</span>
                <div className="item-glow"></div>
              </Link>

              {isAdmin && (
                <Link
                  to="/adminpanel"
                  onClick={() => setIsOpen(false)}
                  className={`menu-item admin-item ${hoveredItem === 'admin' ? 'hovered' : ''}`}
                  onMouseEnter={() => setHoveredItem('admin')}
                  onMouseLeave={() => setHoveredItem(null)}
                >
                  <div className="item-icon">🛡️</div>
                  <span className="item-text">Admin Panel</span>
                  <div className="item-glow"></div>
                </Link>
              )}

              <div className="menu-divider"></div>

              {/* Admin Logout Button */}
              {isAdmin && isAdminLoggedIn && (
                <button
                  onClick={handleAdminLogout}
                  className={`menu-item admin-logout-item ${hoveredItem === 'admin-logout' ? 'hovered' : ''}`}
                  onMouseEnter={() => setHoveredItem('admin-logout')}
                  onMouseLeave={() => setHoveredItem(null)}
                >
                  <div className="item-icon">🛡️</div>
                  <span className="item-text">Admin Logout</span>
                  <div className="item-glow"></div>
                </button>
              )}

              {/* Regular Logout Button */}
              <button
                onClick={handleLogout}
                className={`menu-item logout-item ${hoveredItem === 'logout' ? 'hovered' : ''}`}
                onMouseEnter={() => setHoveredItem('logout')}
                onMouseLeave={() => setHoveredItem(null)}
              >
                <div className="item-icon">🚪</div>
                <span className="item-text">Sign Out</span>
                <div className="item-glow"></div>
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Image Cropper Modal */}
      {showCropper && selectedImage && (
        <ImageCropper
          imageSrc={selectedImage}
          onCrop={handleCropComplete}
          onClose={handleCropCancel}
        />
      )}
    </>
  );
};

export default ProfileDropdown; 